# Modules 9, 12 à 17 rédigés à partir de l'INRS ED 6127 (déc. 2020), S29. Niveaux de preuve : S source lue, R principe à valider.
def Q(i,t,q,o,c,why): return dict(id=i,type=t,q=q,options=o,correct=c,why=why)
NOTE=" Rédigé à partir de l'ED 6127 (2020) seule ; la NF C 18-510 n'a pas été lue : à valider par le formateur. Repères : [S29] = INRS ED 6127 ; [R] = principe de raisonnement à valider."
SYMB="Le symbole se lit en trois caractères : le domaine de tension (B ou H), le type d'opération (0, 1, 2, C, R, S, E…), puis une lettre additionnelle (T, V, N, X) ou un attribut [S29]."

M9=dict(id=9,title="Travaux hors tension B1 · B1V · B2 · B2V",scope="B1, B1V, B2, B2V",niveaux=["B1","B1V","B2","B2V"],statut="nouveau",
 goal="Distinguer exécutant (B1) et chargé de travaux (B2), situer le voisinage renforcé (V) et préparer des travaux électriques hors tension en basse tension.",
 scenario="On vous confie le remplacement d'un coffret de distribution dans un local technique. Une équipe doit y intervenir : qui prépare, qui exécute, qui surveille, et avec quels documents ?",
 sections=[
 ["Exécutant ou chargé de travaux",SYMB+" Le chiffre 1 désigne l'exécutant d'une opération d'ordre électrique, le chiffre 2 le chargé de travaux d'ordre électrique [S29]. Les travaux couvrent par exemple la création ou la modification d'une installation et le remplacement d'un coffret ou d'une armoire [S29]. Le balisage de la zone de travail et la vérification de la bonne exécution des travaux reviennent uniquement au chargé de travaux [S29]."],
 ["Le V : voisinage renforcé","La lettre V indique des travaux au voisinage renforcé : B1V et B2V s'ajoutent à B1 et B2 [S29]. Au voisinage, seules les opérations qui concourent à l'exploitation et à la maintenance de l'installation sont autorisées, les autres sont interdites [S29]. Le symbole V ne se déduit pas du métier : il dépend de la zone d'environnement dans laquelle les travaux se déroulent [R]."],
 ["Ce que la formation doit couvrir","Le module de formation B1, B1V, B2, B2V comprend de quoi caractériser les travaux et connaître leurs limites : hors tension avec ou sans voisinage, en présence de tension, sous tension [S29]. Il comprend aussi le rôle du chargé de consignation et du chargé d'exploitation électrique, dont on respecte les instructions [S29]. S'y ajoutent les mesures de prévention : éliminer le risque, organiser, délimiter, signaler, respecter et faire respecter [S29]."],
 ["Les documents applicables","Les travaux s'appuient sur des documents : instructions de sécurité, attestation de consignation, attestation de première étape de consignation, autorisation de travail, avis de fin de travail [S29]. Le chargé de travaux reçoit l'attestation de consignation avant de commencer [R]. Un exécutant ne commence pas sans avoir reçu les consignes [R]."],
 ["Équipements et pratique","Il faut identifier les équipements de travail utilisés et les risques associés, les vérifier et les utiliser en sécurité [S29]. La formation pratique minimale pour ce groupe de symboles est de 5 h, dont 2 h propres au module [S29]. Les travaux sous tension (T, N) ne sont pas détaillés dans la brochure et ne font pas partie de cette formation [S29]."]],
 decision="On vous demande d'exécuter des travaux dans un local où des pièces nues restent sous tension. Quel symbole faut-il avoir, et que faites-vous si le titre ne le mentionne pas ?",
 answer="Un symbole avec V (B1V ou B2V selon le rôle) [S29]. Si le titre ne le porte pas, on n'exécute pas la tâche et on demande à l'employeur de faire évoluer le titre ou de désigner un titulaire habilité [S29, R].",
 check=["Mon rôle est-il exécutant (1) ou chargé de travaux (2) ?","Le symbole V figure-t-il sur mon titre si les travaux ont lieu au voisinage ?","Ai-je reçu l'attestation de consignation et les instructions de sécurité ?","La zone est-elle balisée, et par qui ?"],
 source="INRS ED 6127 (déc. 2020), §2.3 pp. 10-11, §2.4 pp. 11-12, §5.2 pp. 23-29 [S29].",note="Module nouveau, à valider par le formateur."+NOTE,
 questions=[
  Q("T09-01","s","Dans B2, que désigne le chiffre 2 ?",["Le chargé de travaux d'ordre électrique","L'exécutant d'une opération d'ordre électrique","Le chargé de consignation"],0,"Le chiffre 2 désigne le chargé de travaux [S29] ; 1 l'exécutant [S29]."),
  Q("T09-02","s","Qui assure le balisage de la zone de travail et la vérification de la bonne exécution ?",["Uniquement le chargé de travaux","Tout exécutant","Le chargé de consignation"],0,"Ces deux tâches reviennent uniquement au chargé de travaux [S29]."),
  Q("T09-03","s","Au voisinage, quelles opérations sont autorisées ?",["Celles qui concourent à l'exploitation et à la maintenance de l'installation","Toutes les opérations","Aucune"],0,"Seules les opérations concourant à l'exploitation et à la maintenance sont autorisées [S29]."),
  Q("T09-04","m","Quels documents peut-on utiliser lors de travaux ?",["Instructions de sécurité","Attestation de consignation","Avis de fin de travail","Un simple accord oral sans trace"],[0,1,2],"Instructions de sécurité, attestation de consignation et avis de fin de travail figurent parmi les documents applicables [S29]."),
  Q("T09-05","s","La brochure détaille-t-elle la formation aux travaux sous tension ?",["Non, elle ne les détaille pas","Oui, entièrement","Oui, pour le BT seulement"],0,"La brochure ne détaille pas les formations aux travaux sous tension [S29]."),
 ])

M12=dict(id=12,title="Travaux hors tension H1 · H1V · H2 · H2V",scope="H1, H1V, H2, H2V",niveaux=["H1","H1V","H2","H2V"],statut="nouveau",
 goal="Situer le domaine haute tension, les symboles H1 à H2V et ce que la formation HT ajoute à celle de la basse tension.",
 scenario="Un poste haute tension doit faire l'objet de travaux hors tension. Le client n'a pas précisé s'il s'agit de HTA ou de HTB.",
 sections=[
 ["Les symboles HT","Les symboles H1, H1V, H2 et H2V suivent la même logique que leurs équivalents BT : H pour la haute tension, 1 pour l'exécutant, 2 pour le chargé de travaux, V pour le voisinage renforcé [S29]. En voisinage renforcé, le symbole H0V s'applique aux opérations d'ordre non électrique [S29]."],
 ["HTA ou HTB : le contenu change","Les thèmes de la formation doivent être développés différemment selon le domaine de tension considéré : BT, HTA ou HTB [S29]. Le choix HTA ou HTB n'est pas encore fixé pour cette session : il reste à confirmer avant tout affichage de contenu technique [R]."],
 ["Thèmes techniques propres à la haute tension","Une formation HT comprend un module de thèmes techniques : types, structure et fonctionnement des ouvrages et installations (ligne et poste), fonction des matériels des postes (commande, protection, séparation) [S29]. Elle comprend l'induction et le couplage capacitif avec leurs mesures de prévention, dont la mise en équipotentialité [S29]. Elle comprend aussi le verrouillage et l'interverrouillage, ainsi que les équipements de protection collective et individuelle [S29]."],
 ["Pratique minimale","La formation pratique minimale est de 6,5 h pour H1, H1V, H2, H2V et H2V Essai : 3 h de thèmes communs, 1,5 h pour les spécificités HTA ou HTB et 2 h pour le module [S29]."]],
 decision="Un participant demande à passer H2V sans avoir précisé le domaine HTA ou HTB. Que faites-vous ?",
 answer="On ne fixe pas le contenu technique : on fait préciser le domaine et les installations par l'employeur avant de choisir les thèmes et les travaux pratiques [S29, R].",
 check=["Le domaine HTA ou HTB est-il précisé ?","Le symbole comporte-t-il V si le voisinage renforcé est concerné ?","Les installations de la formation pratique sont-elles représentatives ?"],
 source="INRS ED 6127 (déc. 2020), §2.3 pp. 10-11, §5.2 pp. 23-30 [S29].",note="Module nouveau, à valider par le formateur. Domaine HTA ou HTB non confirmé : aucune valeur technique n'est affichée."+NOTE,
 questions=[
  Q("T12-01","s","Le contenu d'une formation HT est-il identique pour HTA et HTB ?",["Non, il se développe différemment selon le domaine","Oui, toujours","Seul le nombre de questions change"],0,"Les thèmes se développent différemment selon BT, HTA ou HTB [S29]."),
  Q("T12-02","s","Quelle durée de formation pratique minimale pour H1, H1V, H2, H2V ?",["6,5 h","2 h","3 h"],0,"6,5 h au total : thèmes communs, spécificités HT et module [S29]."),
  Q("T12-03","m","Quels thèmes techniques une formation HT comprend-elle ?",["Induction et couplage capacitif","Verrouillage et interverrouillage","Types et structure des postes et lignes","Calcul d'un bilan carbone"],[0,1,2],"Induction, verrouillage et structure des ouvrages font partie du module de thèmes techniques [S29]."),
 ])

M13=dict(id=13,title="Consignation HC",scope="HC",niveaux=["HC"],statut="nouveau",
 goal="Appliquer les étapes d'une consignation en haute tension, utiliser les documents applicables et situer la réquisition.",
 scenario="Un ouvrage HT doit être consigné pour permettre des travaux. Vous êtes le chargé de consignation : avec qui échangez-vous, quels documents établissez-vous ?",
 sections=[
 ["Le rôle du chargé de consignation","Le chargé de consignation identifie le chargé d'exploitation électrique, connaît son rôle et échange avec lui les informations [S29]. Il suit les instructions reçues [S29]. Le symbole HC concerne la consignation d'un ouvrage ou d'une installation électrique en haute tension [S29]."],
 ["Étapes et documents","Le chargé de consignation réalise les étapes de la consignation et utilise les documents applicables, dont l'attestation de consignation en une ou deux étapes et l'avis de fin de travail [S29]. L'ordre général des étapes (séparation, condamnation, identification, vérification d'absence de tension, mise à la terre et en court-circuit) est celui du module BC [S22]."],
 ["La réquisition","La formation HC comprend la description d'un régime de réquisition, l'analyse des risques et le renseignement d'un avis de réquisition, si nécessaire [S29]. Le cas de réquisition dépend de l'organisation de l'installation : il se précise avec le client [R]."],
 ["Pratique minimale","La formation pratique minimale pour HC est de 6,5 h, comme pour les travaux HT : 3 h de thèmes communs, 1,5 h de spécificités HT et 2 h pour le module [S29]."]],
 decision="Les travaux sont terminés, mais l'avis de fin de travail n'est pas encore rendu. Peut-on déconsigner ?",
 answer="Non [S29]. La déconsignation suit l'avis de fin de travail et l'organisation prévue avec le chargé d'exploitation [S29, R].",
 check=["Le chargé d'exploitation est-il identifié ?","L'attestation (une ou deux étapes) est-elle établie ?","La réquisition est-elle nécessaire ?","L'avis de fin de travail est-il rendu avant la déconsignation ?"],
 source="INRS ED 6127 (déc. 2020), §2.4 p. 12, §5.2 pp. 23-30 [S29] ; module BC de la plateforme Panzani [S22].",note="Module nouveau, à valider par le formateur. Domaine HTA ou HTB à confirmer."+NOTE,
 questions=[
  Q("T13-01","s","Avec qui le chargé de consignation échange-t-il les informations ?",["Le chargé d'exploitation électrique","Le premier exécutant disponible","Aucun interlocuteur"],0,"Il identifie le chargé d'exploitation et échange avec lui [S29]."),
  Q("T13-02","m","Quels documents interviennent lors d'une consignation ?",["L'attestation de consignation","L'avis de fin de travail","Un avis de réquisition, si nécessaire"],[0,1,2],"Attestation (une ou deux étapes), avis de fin de travail, et avis de réquisition si nécessaire [S29]."),
 ])

M14=dict(id=14,title="Opération spécifique HE Manœuvre",scope="HE Manœuvre",niveaux=["HE"],statut="nouveau",
 goal="Situer les manœuvres HE, ce que l'attribut Manœuvre permet et ce qu'il n'autorise pas.",
 scenario="On vous demande de manœuvrer un appareil de coupure d'un poste HT selon une fiche de manœuvre. Vous n'êtes ni chargé de travaux ni chargé de consignation.",
 sections=[
 ["Un symbole à compléter par un attribut","Les symboles BE et HE doivent être complétés par un attribut : Essai, Vérification, Mesurage ou Manœuvre [S29]. HE seul ne dit donc pas quelle opération est permise [S29, R]. HE Manœuvre couvre la manœuvre de matériel pour mettre hors ou sous tension un équipement ou une installation [S29]."],
 ["Exécuter une manœuvre","La pratique à évaluer est de réaliser une manœuvre d'exploitation ou de consignation dans le respect des instructions et des documents, comme la fiche de manœuvre [S29]. Il faut connaître les limites de l'habilitation HE ou BE (manœuvres permises) [S29]."],
 ["Manœuvres en HTB","Il existe un module de formation propre aux manœuvres en HTB [S29]. Les manœuvres en HTA suivent le module des manœuvres de la formation de base [S29]. Le choix HTA ou HTB reste à confirmer [R]."],
 ["Durée de pratique","La formation pratique minimale pour HE Manœuvre HTB est de 5 h [S29]."]],
 decision="Un appareil refuse de se fermer. Que faites-vous ?",
 answer="On s'arrête, on décrit le fait au demandeur et on laisse la prise en charge à l'interlocuteur compétent : la manœuvre ne devient pas un dépannage [S29, R].",
 check=["La fiche de manœuvre est-elle disponible ?","L'appareil est-il identifié ?","L'opération est-elle bien une manœuvre ?"],
 source="INRS ED 6127 (déc. 2020), §2.3 pp. 10-11, §2.4 p. 12, §5.2 p. 24 [S29].",note="Module nouveau, à valider par le formateur. Domaine HTA ou HTB à confirmer."+NOTE,
 questions=[
  Q("T14-01","s","HE seul suffit-il pour savoir quelle opération est permise ?",["Non, il faut un attribut","Oui","Seulement en HTB"],0,"BE et HE se complètent par Essai, Vérification, Mesurage ou Manœuvre [S29]."),
  Q("T14-02","s","Quel document guide une manœuvre d'exploitation ou de consignation ?",["La fiche de manœuvre","Le carnet de santé","Le plan de situation du bâtiment"],0,"La pratique évalue le respect des instructions et des documents, comme la fiche de manœuvre [S29]."),
 ])

M15=dict(id=15,title="BE : mesurage · vérification · essai",scope="BE Mesurage, Vérification, Essai",niveaux=["BE"],statut="nouveau",
 goal="Distinguer mesurage, vérification et essai, et connaître ce que les attributs BE permettent.",
 scenario="On vous demande de contrôler un circuit et de mesurer une grandeur sur un équipement. Vous devez dire de quelle opération il s'agit avant de commencer.",
 sections=[
 ["Trois attributs, trois formations","BE doit être complété par un attribut : Mesurage, Vérification ou Essai (ou Manœuvre) [S29]. Le mesurage et la vérification partagent un module de formation, l'essai a le sien [S29]. La vérification comprend l'examen visuel, l'essai et le mesurage [S29]."],
 ["Ce que couvre le module mesurage et vérification","Il comprend la fonction des matériels (coupure, protection, séparation), l'identification du chargé d'exploitation électrique et l'échange avec lui [S29]. Il comprend les équipements de travail utilisés et leurs risques, les documents applicables (autorisation de travail, instructions de sécurité) et les mesures de prévention [S29]."],
 ["Ce que couvre le module essai","Le module essai ajoute les symboles et leurs limites pour les personnes intervenant lors des essais [S29]. Il ajoute les consignes pour les essais particuliers (source autonome, recherche de défaut de câble, laboratoire et plate-forme d'essais) [S29]. Il comprend aussi la consignation pour son propre compte [S29]."],
 ["Pratique minimale","La formation pratique minimale est de 4 h pour BE Mesurage et BE Vérification, et de 5 h pour BE Essai [S29]."]],
 decision="Un collègue BE Mesurage propose de remplacer un composant défectueux après l'avoir mesuré. Est-ce son rôle ?",
 answer="Non, mesurer n'autorise pas à remplacer [S29]. Il rend compte et laisse l'opération au titulaire du symbole adapté [S29, R].",
 check=["Mon attribut est-il Mesurage, Vérification, Essai ou Manœuvre ?","L'opération demandée correspond-elle à cet attribut ?","L'autorisation de travail est-elle donnée ?"],
 source="INRS ED 6127 (déc. 2020), §2.3 pp. 10-11, §5.2 pp. 24, 29-30 [S29].",note="Module nouveau, à valider par le formateur."+NOTE,
 questions=[
  Q("T15-01","s","Quelle durée de pratique minimale pour BE Essai ?",["5 h","4 h","2 h"],0,"5 h pour BE Essai, 4 h pour Mesurage et Vérification [S29]."),
  Q("T15-02","m","La vérification comprend :",["L'examen visuel","L'essai","Le mesurage","La modification de l'installation"],[0,1,2],"Examen visuel, essai et mesurage [S29]."),
  Q("T15-03","s","BE Mesurage autorise-t-il à remplacer un composant ?",["Non","Oui","Oui, hors tension"],0,"Le symbole se limite à l'opération de son attribut [S29, R]."),
 ])

M16=dict(id=16,title="Travaux pratiques individualisés et évaluations",scope="Tous",niveaux=["Tous"],statut="nouveau",
 goal="Organiser les travaux pratiques par symbole, mener l'évaluation des savoirs et des savoir-faire, et formuler l'avis après formation.",
 scenario="Quatre à dix stagiaires, des symboles différents : chaque stagiaire doit réaliser lui-même les opérations de son symbole, puis être évalué.",
 sections=[
 ["Une pratique individuelle","La formation doit comporter une partie pratique, de préférence dans l'environnement habituel de l'apprenant ou dans un environnement aussi proche que possible du réel, sur des installations représentatives [S29]. Pour les modules spécifiques, l'apprenant réalise lui-même les opérations [S29]. Pour les thèmes communs, la formation pratique peut être individuelle ou de groupe [S29]."],
 ["Évaluation des savoirs","L'évaluation des savoirs se fait par un QCM de 15 questions minimum, constitué de façon aléatoire à partir d'une base d'au moins cinq fois plus de questions par thème [S29]. Les thèmes sont les dangers de l'électricité, les distances et zones d'environnement, les limites des opérations associées au symbole et les mesures de protection [S29]. L'apprenant doit obtenir au minimum 70 % de bonnes réponses [S29]. Les distances et zones comme les limites du symbole représentent chacune au moins 30 % des questions [S29]."],
 ["Évaluation des savoir-faire","Elle se fait après l'évaluation positive des savoirs, à partir d'une ou plusieurs situations de travail [S29]. Trois critères : sans erreur, erreur mineure sans conséquence pour la sécurité des personnes, erreur majeure avec conséquence directe [S29]. Les critères d'acceptation sont deux erreurs mineures au maximum et aucune erreur majeure [S29]."],
 ["Les savoir-faire par symbole","Tous les symboles évaluent l'identification des risques, un comportement adapté et le compte rendu de l'opération [S29]. Chaque symbole ajoute les siens : baliser et surveiller pour le chargé de chantier et de travaux, réaliser une consignation pour BC et HC, une intervention BT générale pour BR, une intervention élémentaire et un réarmement pour BS, une manœuvre pour BE et HE Manœuvre [S29]."],
 ["L'avis après formation","À l'issue de la formation, le formateur formule un avis après formation et le remet à l'employeur [S29]. L'employeur délivre ensuite l'habilitation : ni la formation ni un score ne valent habilitation [S29]."]],
 decision="Un stagiaire obtient 80 % au QCM mais commet une erreur majeure en pratique. Quel avis ?",
 answer="Les savoirs sont acquis, mais l'évaluation des savoir-faire n'est pas validée : aucune erreur majeure n'est tolérée [S29].",
 check=["Chaque stagiaire opère-t-il lui-même ?","Le QCM tire-t-il ses questions au hasard dans une base suffisante ?","Les critères pratiques sont-ils appliqués à la lettre ?","L'avis est-il remis à l'employeur ?"],
 source="INRS ED 6127 (déc. 2020), §5.1 pp. 21-22, §5.4 pp. 33-35, §7.2 [S29].",note="Module nouveau, à valider par le formateur. Les grilles d'observation par symbole sont à créer."+NOTE,
 questions=[
  Q("T16-01","s","Quel score minimal au QCM de savoirs ?",["70 %","50 %","90 %"],0,"70 % de bonnes réponses au minimum [S29]."),
  Q("T16-02","s","Combien d'erreurs mineures au maximum en évaluation pratique ?",["Deux, et aucune majeure","Aucune","Cinq"],0,"Deux erreurs mineures au maximum, aucune majeure [S29]."),
  Q("T16-03","s","Combien de questions au minimum dans le QCM ?",["15","10","50"],0,"15 questions minimum [S29]."),
  Q("T16-04","s","Qui délivre l'habilitation ?",["L'employeur, après l'avis du formateur","Le formateur","Le stagiaire lui-même"],0,"Le formateur remet un avis après formation ; l'employeur habilite [S29]."),
 ])

M17=dict(id=17,title="Spécificités métier : sécurité incendie (optionnel)",scope="Installations de sécurité incendie",niveaux=["SSI"],statut="nouveau",
 goal="Situer les opérations courantes sur des installations de sécurité incendie dans la logique de l'habilitation et décider, avec l'employeur, du symbole qui les couvre.",
 scenario="Un technicien de sécurité incendie doit contrôler les batteries d'une centrale d'alarme, remplacer un détecteur en hauteur et essayer un déclencheur manuel. Quelles opérations relèvent de quel symbole ?",
 sections=[
 ["Partir de l'opération, pas du métier","Le choix d'un symbole dépend de l'activité confiée et de l'environnement électrique [S29]. Le métier ne détermine pas le symbole : il se choisit à partir de la nature de l'opération et de la tension [S29, R]. Les listes de symboles d'ADI sécurité n'ont pas été communiquées : tout rattachement ci-dessous reste à décider avec l'employeur [R]."],
 ["Opérations courantes et symboles à étudier","Le contrôle d'une grandeur sur une alimentation relève d'une opération spécifique : l'attribut Mesurage ou Vérification de BE est à examiner [S29, R]. La manœuvre d'un dispositif de coupure relève de l'attribut Manœuvre [S29]. Une intervention sur un équipement avec recherche de panne ou remplacement relève de l'intervention générale BR, dans ses limites [S29, R]. Le remplacement de matériel défectueux (relais, borniers) fait partie des opérations BR [S29]."],
 ["Ce qui s'ajoute à l'électricité","Une pose de détecteur en hauteur ajoute un risque de chute : il faut organiser le travail en tenant compte à la fois de la hauteur et de la proximité de conducteurs [R]. Une alimentation de secours par batteries est une source qu'il faut identifier avant toute intervention [R]. Les consignes du fabricant de la centrale complètent l'habilitation [R]."],
 ["Un cadre à construire avec l'employeur","L'employeur définit, sous forme de cahier des charges, les opérations, l'organisation et le matériel pour choisir les symboles [S29]. Pour cette session, la liste des opérations d'ADI sécurité sera à fournir par le formateur à partir des cas réels [R]."]],
 decision="Un technicien est habilité BS. On lui demande de rechercher la cause d'un défaut d'alimentation d'une centrale. Que décidez-vous ?",
 answer="La recherche de panne dépasse l'intervention élémentaire BS [S29]. Elle relève de l'intervention générale BR ou d'un autre symbole adapté, on arrête et on demande le relais [S29, R].",
 check=["L'opération est-elle nommée précisément ?","Quelles sources d'alimentation (secteur, batteries) sont présentes ?","Le titre couvre-t-il l'opération ?","Le travail en hauteur est-il organisé ?"],
 source="INRS ED 6127 (déc. 2020), §2.4 pp. 11-12 [S29] ; hypothèse de travail pour ADI sécurité, aucune liste de symboles fournie [R].",note="Module nouveau, à valider par le formateur. Aucune valeur technique : à construire avec les cas réels fournis par le formateur."+NOTE,
 questions=[
  Q("T17-01","s","Qu'est-ce qui détermine le symbole d'habilitation ?",["La nature de l'opération et l'environnement électrique","L'intitulé du poste seulement","L'ancienneté"],0,"Le choix tient compte de l'activité confiée et de l'environnement électrique [S29]."),
  Q("T17-02","s","La recherche de panne relève-t-elle du BS ?",["Non, elle relève de l'intervention générale BR","Oui","Seulement hors tension"],0,"La recherche de panne fait partie des opérations BR [S29]."),
  Q("T17-03","s","Une batterie de secours est :",["Une source à identifier avant toute intervention","Sans danger car elle est faible","Hors du périmètre de l'habilitation"],0,"Toutes les sources doivent être identifiées [R]."),
 ])
MODULES=[M9,M12,M13,M14,M15,M16,M17]
VALEURS={'5':('S','S29 : 5 h de pratique'),'2':('S','S29 : chiffre 2 ; 2 h du module'),'1':('S','S29 : chiffre 1 exécutant'),'0':('S','S29 : chiffre 0'),'3':('S','S29 : 3 h de thèmes communs'),'6,5':('S','S29 : 6,5 h'),'1,5':('S','S29 : 1,5 h'),'4':('S','S29 : 4 h'),'15':('S','S29 : 15 questions minimum'),'70':('S','S29 : 70 %'),'30':('S','S29 : 30 % minimum'),'80':('D','distracteur : score fictif du stagiaire'),'50':('D','distracteur'),'90':('D','distracteur')}

# ---------------- Enrichissement 14/11/2026 : modules HT et BE (ED 6127, S29 ; ordre de consignation S22) ----------------
def _add(m,sections,questions):
    m['sections'].extend(sections); m['questions'].extend(questions)
_add(M12,[
 ["Ce que le module « travaux » demande de savoir","Caractériser les travaux et connaître leurs limites : hors tension, avec ou sans voisinage, en présence de tension, sous tension [S29]. Connaître le rôle du chargé de consignation et du chargé d'exploitation électrique, respecter leurs instructions et échanger les informations [S29]. Appliquer les mesures de prévention : éliminer le risque, organiser, délimiter, signaler, respecter et faire respecter [S29]. Utiliser les documents applicables : instructions de sécurité, attestation de consignation, attestation de première étape de consignation, autorisation de travail, avis de fin de travail [S29]."],
 ["Induction, couplage capacitif, équipotentialité","Le module de thèmes techniques HT demande de comprendre l'induction et le couplage capacitif et d'appliquer les mesures de prévention associées, dont la mise en équipotentialité [S29]. Il demande aussi d'expliquer le fonctionnement et de manœuvrer les dispositifs de verrouillage et d'interverrouillage [S29]. Les équipements de protection collective et individuelle sont à identifier, vérifier et utiliser [S29]."],
 ["Les savoir-faire évalués selon le symbole","Pour H1 et H1V, on évalue le respect des consignes de sécurité pour exécuter les travaux et la mise en œuvre des équipements de protection individuelle [S29]. Pour H1V et H2V, on évalue en plus la mise en œuvre des équipements de protection collective, comme la nappe isolante ou l'écran [S29]. Pour H2 et H2V, on évalue la préparation et la direction des travaux, la rédaction ou le renseignement des documents, le balisage et la surveillance de la zone [S29]."],
 ["Pas-à-pas : préparer et exécuter des travaux hors tension en HT","1) Faire préciser le domaine (HTA ou HTB), l'installation et les travaux avant de choisir les thèmes [S29, R].\n2) Identifier le chargé d'exploitation électrique et le chargé de consignation [S29].\n3) Obtenir l'attestation de consignation avant de commencer les travaux [S29, R].\n4) Organiser, délimiter et signaler la zone de travail [S29].\n5) Identifier, vérifier et mettre en œuvre les équipements de protection [S29].\n6) Exécuter les travaux dans les limites du symbole, en respectant les instructions de sécurité [S29].\n7) Rendre compte, puis clôturer par l'avis de fin de travail [S29, R]."],
],[
 Q("T12-04","s","Dans H2V, que précise la lettre V ?",["Le voisinage renforcé","Une validité annuelle","Le chargé de consignation"],0,"V désigne le voisinage renforcé, comme en basse tension [S29]."),
 Q("T12-05","s","Quel symbole correspond au chargé de travaux d'ordre électrique en haute tension ?",["H2","H1","HC"],0,"Le chiffre 2 désigne le chargé de travaux ; 1 l'exécutant [S29]."),
 Q("T12-06","m","Quels savoir-faire sont évalués pour H2 et H2V ?",["Préparer et diriger les travaux","Rédiger ou compléter les documents","Baliser et surveiller la zone","Réaliser seul un essai de câble en laboratoire"],[0,1,2],"Préparation, direction, documents, balisage et surveillance figurent dans les savoir-faire de H2 et H2V [S29]."),
 Q("T12-07","s","Quelle mesure de prévention associe-t-on à l'induction et au couplage capacitif ?",["La mise en équipotentialité","L'augmentation de la tension","Le port de gants seul, sans autre mesure"],0,"La formation HT cite la mise en équipotentialité parmi les mesures associées [S29]."),
 Q("T12-08","m","Quelles sont des mesures de prévention lors des travaux ?",["Éliminer le risque","Organiser et délimiter","Signaler","Se fier à son habitude du site"],[0,1,2],"Éliminer le risque, organiser, délimiter, signaler, respecter et faire respecter [S29]."),
 Q("T12-09","s","Que doit savoir faire le stagiaire HT vis-à-vis du verrouillage et de l'interverrouillage ?",["Expliquer leur fonctionnement et manœuvrer les dispositifs","Les contourner si le travail presse","Les ignorer, car ils concernent l'exploitant seul"],0,"Le module de thèmes techniques demande d'expliquer le fonctionnement et de manœuvrer ces dispositifs [S29]."),
 Q("T12-10","s","Quel document reçoit-on avant de commencer des travaux hors tension après une consignation ?",["L'attestation de consignation","Une fiche de paie","Un devis"],0,"L'attestation de consignation fait partie des documents applicables aux travaux [S29] ; elle est reçue avant de commencer [R]."),
])
_add(M13,[
 ["Une analyse préalable avant de consigner","Avant la consignation, on réalise une analyse préalable de l'opération, comme pour BC, BR et BS [S29]. On rédige ou on complète les documents propres à l'opération [S29]. La consignation en une étape fait partie des savoir-faire évalués pour BC et HC [S29]."],
 ["Une ou deux étapes : les documents","Les documents prévoient une attestation de consignation en une ou deux étapes et, si besoin, une attestation de première étape [S29]. Le circuit exact de ces documents en haute tension se précise avec l'exploitant de l'installation [R]. Le chargé de consignation connaît la fonction des matériels : coupure, protection, séparation [S29]."],
 ["Les thèmes techniques HT qui servent la consignation","Le module de thèmes techniques HT apporte la structure des ouvrages (ligne et poste), la fonction des matériels des postes (commande, protection, séparation) et le verrouillage et l'interverrouillage [S29]. Les équipements de protection collective et individuelle sont à identifier, vérifier et utiliser [S29]."],
 ["Pas-à-pas : consigner et déconsigner","1) Identifier le chargé d'exploitation électrique et échanger les informations avec lui [S29].\n2) Réaliser l'analyse préalable de l'opération [S29].\n3) Séparer l'ouvrage des sources de tension [S22].\n4) Condamner les organes de séparation [S22].\n5) Identifier l'ouvrage à consigner [S22].\n6) Vérifier l'absence de tension [S22].\n7) Mettre à la terre et en court-circuit [S22].\n8) Établir l'attestation de consignation, puis attendre l'avis de fin de travail avant de déconsigner [S29]."],
],[
 Q("T13-03","o","Remettez dans l'ordre les étapes d'une consignation.",["Séparation","Condamnation","Identification","Vérification d'absence de tension","Mise à la terre et en court-circuit"],[0,1,2,3,4],"L'ordre général est séparation, condamnation, identification, vérification d'absence de tension, mise à la terre et en court-circuit [S22]."),
 Q("T13-04","s","Que réalise-t-on avant de consigner ?",["Une analyse préalable de l'opération","Rien : on consigne tout de suite","Un essai sous tension"],0,"Une analyse préalable est demandée pour la consignation [S29]."),
 Q("T13-05","m","Que décrit la formation HC pour la réquisition ?",["Un régime de réquisition","L'analyse des risques","Le renseignement d'un avis de réquisition, si nécessaire","Le calcul d'une facture d'énergie"],[0,1,2],"Régime de réquisition, analyse des risques et avis de réquisition, si nécessaire [S29]."),
 Q("T13-06","s","Quelle est la durée de pratique minimale pour HC ?",["6,5 h","2 h","5 h"],0,"HC : 6,5 h, comme les travaux HT [S29]."),
 Q("T13-07","s","À quoi sert l'attestation de première étape de consignation ?",["Elle fait partie des documents quand la consignation se fait en deux étapes","Elle remplace l'avis de fin de travail","Elle donne l'habilitation au stagiaire"],0,"Les documents prévoient une attestation en une ou deux étapes et une attestation de première étape [S29]."),
 Q("T13-08","s","Quand peut-on déconsigner ?",["Après l'avis de fin de travail","Dès que les travailleurs ont quitté le poste, sans document","Avant la vérification d'absence de tension"],0,"La déconsignation suit l'avis de fin de travail et l'organisation prévue avec le chargé d'exploitation [S29, R]."),
 Q("T13-09","s","Que représente HC ?",["La consignation d'un ouvrage ou d'une installation en haute tension","Le chargé de chantier en basse tension","Une manœuvre en basse tension"],0,"HC concerne la consignation en haute tension [S29]."),
])
_add(M14,[
 ["Les thèmes propres aux manœuvres","Le module des manœuvres demande d'identifier les matériels électriques dans leur environnement, de reconnaître leurs caractéristiques et leur fonction [S29]. Il demande d'identifier, vérifier et utiliser les équipements de protection individuelle [S29]. Il demande de connaître les limites de l'habilitation BE ou HE (manœuvres permises) et d'évaluer les risques liés aux manœuvres [S29]."],
 ["Les acteurs et les échanges","Il faut connaître les acteurs concernés par les manœuvres : le chargé d'exploitation électrique et le chargé de consignation [S29]. Il faut échanger avec eux les informations et les documents pertinents [S29]. Le compte rendu de l'opération réalisée fait partie des savoir-faire évalués pour tous les symboles [S29]."],
 ["Ce que la haute tension ajoute à la manœuvre","Le module de thèmes techniques HT apporte la structure des ouvrages (ligne et poste), la fonction des matériels des postes (commande, protection, séparation) et le verrouillage et l'interverrouillage [S29]. Il comprend l'explication du fonctionnement des dispositifs de verrouillage et d'interverrouillage et leur manœuvre [S29]."],
 ["Pas-à-pas : exécuter une manœuvre","1) Vérifier que l'opération demandée est bien une manœuvre couverte par le symbole HE et son attribut Manœuvre [S29, R].\n2) Se procurer la fiche de manœuvre et les instructions de sécurité [S29].\n3) Identifier l'appareil et son environnement [S29].\n4) Identifier, vérifier et mettre les équipements de protection individuelle [S29].\n5) Exécuter la manœuvre dans l'ordre de la fiche, en respectant le verrouillage et l'interverrouillage [S29, R].\n6) En cas d'anomalie, s'arrêter et en rendre compte sans dépanner [R].\n7) Rendre compte au chargé d'exploitation électrique ou au chargé de consignation [S29]."],
],[
 Q("T14-03","m","Quels acteurs sont concernés par les manœuvres ?",["Le chargé d'exploitation électrique","Le chargé de consignation","Le chargé de travaux d'un autre site sans lien avec l'ouvrage"],[0,1],"Le module des manœuvres cite le chargé d'exploitation électrique et le chargé de consignation [S29]."),
 Q("T14-04","s","Quelle pratique est évaluée pour HE Manœuvre ?",["Réaliser une manœuvre d'exploitation ou de consignation selon les instructions et documents","Réaliser seul un essai de laboratoire","Diriger des travaux"],0,"Savoir-faire évalué : manœuvre d'exploitation ou de consignation avec fiche de manœuvre [S29]."),
 Q("T14-05","s","Quelle est la durée de pratique minimale pour HE Manœuvre HTB ?",["5 h","2 h","6,5 h"],0,"HE Manœuvre HTB : 5 h [S29]."),
 Q("T14-06","s","Que faire en cas d'anomalie pendant une manœuvre ?",["S'arrêter et rendre compte","Forcer la commande","Dépanner l'appareil soi-même"],0,"On s'arrête et on rend compte : la manœuvre ne devient pas un dépannage [S29, R]."),
 Q("T14-07","s","Pour quels symboles le compte rendu de l'opération est-il évalué ?",["Tous les symboles","Seulement les chargés de travaux","Seulement HC"],0,"Le compte rendu fait partie des savoir-faire évalués pour tous les symboles [S29]."),
 Q("T14-08","s","Que comprend le module de thèmes techniques HT à propos du verrouillage ?",["Expliquer le fonctionnement et manœuvrer les dispositifs de verrouillage et d'interverrouillage","Les démonter pour les contrôler","Les ignorer pendant la manœuvre"],0,"Le module demande d'expliquer le fonctionnement et de manœuvrer ces dispositifs [S29]."),
])
_add(M15,[
 ["Mesurer, vérifier, essayer : les savoir-faire évalués","Pour BE Mesurage et Vérification, on évalue la réalisation d'un mesurage ou d'une vérification, qui comprend l'examen visuel, l'essai et le mesurage [S29]. Pour BE Essai, on évalue la réalisation d'un essai et d'un mesurage seul ou à plusieurs et d'une consignation pour son propre compte [S29]. L'identification, la vérification et la mise en œuvre des équipements de protection individuelle sont évaluées pour BE et HE [S29]."],
 ["Mesurage et vérification : BE ou HE","Le module mesurage et vérification s'applique à BE et à HE [S29]. La pratique minimale est de 5,5 h pour HE Mesurage et HE Vérification, de 4 h pour BE Mesurage et BE Vérification [S29]. La réquisition ne concerne que le HE Essai, si nécessaire [S29]."],
 ["Pas-à-pas : mesurer ou vérifier","1) Nommer l'opération : mesurage, vérification ou essai [S29, R].\n2) Contrôler que l'attribut du titre correspond à cette opération [S29].\n3) Identifier le chargé d'exploitation électrique et obtenir l'autorisation de travail et les instructions de sécurité [S29].\n4) Identifier l'équipement de travail, le vérifier et connaître ses risques [S29].\n5) Appliquer les mesures de prévention : éliminer le risque, organiser, délimiter, signaler [S29].\n6) Réaliser l'opération sans sortir de son attribut [S29, R].\n7) Rendre compte au chargé d'exploitation électrique [S29]."],
],[
 Q("T15-04","s","Quelle est la durée minimale de pratique pour HE Mesurage et HE Vérification ?",["5,5 h","4 h","2 h"],0,"HE Mesurage et HE Vérification : 5,5 h ; BE Mesurage et BE Vérification : 4 h [S29]."),
 Q("T15-05","s","Que doit-on faire avant de mesurer ou d'essayer ?",["Nommer l'opération et vérifier que l'attribut du titre la couvre","Commencer et régulariser ensuite","Demander à un collègue non habilité"],0,"On vérifie que l'opération correspond à l'attribut du titre [S29, R]."),
 Q("T15-06","m","Quels savoir-faire sont évalués pour BE Essai ?",["Réaliser un essai","Réaliser un mesurage, seul ou à plusieurs","Réaliser une consignation pour son propre compte","Diriger des travaux hors tension"],[0,1,2],"Essai, mesurage seul ou à plusieurs et consignation pour son propre compte [S29]."),
 Q("T15-07","s","Pour quel symbole la réquisition est-elle prévue, si nécessaire ?",["HE Essai","BE Mesurage","B0"],0,"La réquisition concerne uniquement HE Essai, si nécessaire [S29]."),
 Q("T15-08","s","Quels équipements de protection la formation BE et HE demande-t-elle de maîtriser ?",["Identifier, vérifier et mettre en œuvre les équipements de protection individuelle","Aucun","Seulement les équipements collectifs"],0,"EPI évalués pour BE et HE [S29]."),
 Q("T15-09","s","Quels essais particuliers le module essai ajoute-t-il ?",["Source autonome, recherche de défaut de câble, laboratoire et plate-forme d'essais","Essais de résistance de matériaux de construction","Aucun essai particulier"],0,"Le module essai ajoute des consignes pour ces essais particuliers [S29]."),
])
